window.PHOTOS = {
  "army":          ["assets/archive/army.webp", "h43 old", "Прислал оттуда, 80-й. Пишет: «Мам, тут тепло и кормят». Рядом Лёша Тихонов, Валентины Ивановны сын. Худые оба.", ""],
  "sgushchenka":   ["assets/archive/sgushchenka.webp", "h32 old", "Афган, весна 80-го. Одна банка сгущёнки на двоих. Лёха открывал её штык-ножом и считает, что раз открывал он, ему положено две трети.", ""],
  "dembel":        ["assets/archive/dembel.webp", "v34 old", "81-й. Вернулись. Снимала Валентина Ивановна, у меня руки не слушались.", ""],
  "school":        ["assets/archive/school.webp", "h32 old", "От автора: Школа милиции, 1982-й. Лёша вытащил Витю из пьяного года после армии и привёл сюда за руку. Конспект пишет Витя, Лёша списывает и ещё критикует почерк. Так и учились все три года.", ""],
  "militia-2":     ["assets/archive/militia-2.webp", "h43", "Тоже 10 ноября. Лёха раз в год в полной форме, вот он. Весь отдел смеётся: фуражку он утром полчаса отбирал у Пирата.", "'94 11 10"],
  "militia-1":     ["assets/archive/militia-1.webp", "h43", "10 ноября 95-го. Оливье, шпроты, «Столичная». Мой тост: три слова. Лёхин: триста.", "'95 11 10"],
  "viktor-kids":   ["assets/archive/viktor-kids.webp", "h43", "Лето 95-го, двор у Маринки. Петька в моей фуражке, Анютка на шее. Снимала Маринка. Фуражку потом искали всем двором.", "'95 7 2"],
  "fishing":       ["assets/archive/fishing.webp", "h43", "Вуокса, сентябрь 95-го. Щуку поймал я. Лёха до сих пор врёт, что она сама прицепилась.", "'95 9 24"],
  "viktor-marina-kids": ["assets/archive/viktor-marina-kids.webp", "h43", "Октябрь 95-го, кольцо у Стачек. Маринка, мелкие и я в роли лошади. Щёлкнул прохожий.", "'95 10 8"],
  "viktor-naida":  ["assets/archive/viktor-naida.webp", "h43", "От автора: Зима 1996-го. Каждый вечер Витя и Найда сидят на одной и той же лавке у подъезда. Он рассказывает ей про день, она слушает и ни с чем не спорит.", "'96 1 21"],
  "naida-home":    ["assets/archive/naida-home.webp", "h43", "От автора: Пока Витя на работе, Найда лежит в прихожей. Его тапок охраняет, сушки бабы Вали держит при себе. Делиться не собирается.", "'96 2 18"],
  "parents-wedding": ["assets/archive/parents-wedding.webp", "h43 old", "Май 58-го. Пиджак Сене одолжил сосед: рукава короткие, в плечах трещит. Смеялись от самого загса, серьёзной карточки так и не вышло. И не надо.", ""],
  "papa-forma":     ["assets/archive/papa-forma.webp", "v34 old", "Сеня, 52-й, лейтенант. Это ещё до меня, карточку выпросила у его мамы. Смотрит строго, а сам потом полгода не решался позвать меня в кино.", ""],
  "papa-kids":      ["assets/archive/papa-kids.webp", "h43 old", "Лето 67-го, наш двор на Стачек. Марише год, Вите шесть. Сеня держит её, как батон из булочной, а Витя изо всех сил хмурится, чтобы быть как папа. Похож.", ""],
  "mama-uchitel":   ["assets/archive/mama-uchitel.webp", "v34 old", "75-й, сочинения восьмого «Б». Снял Витя на папин «ФЭД» и сказал: «Мам, улыбнись, это же не двойки». Двойки там тоже были.", ""],
  "viktor-bukvar":  ["assets/archive/viktor-bukvar.webp", "v34 old", "Зима 66-го. Учим буквы. Через месяц Витя читал сам, а через год таскал у меня тетради с сочинениями и проверял за меня ошибки.", ""],
  "viktor-1sept":   ["assets/archive/viktor-1sept.webp", "v34 old", "1 сентября 68-го. Гладиолусы больше Витюши. Мариша вцепилась в брата и не отпускала, в класс пришлось вести обоих. За парту его посадили с рыжим Лёшей Тихоновым, Валентины Ивановны сыном. К пятнице было не разлучить.", ""],
  "viktor-syrniki": ["assets/archive/viktor-syrniki.webp", "h43 old", "Воскресенье, 71-й. Сырники по моей тетрадке, сам. Первые три сгорели, Мариша их съела и сказала, что так и задумано.", ""],
  "viktor-sanki":   ["assets/archive/viktor-sanki.webp", "h43 old", "Январь 73-го. Катал Маришу на санках до булочной и обратно, три круга. Варежку нашли только весной.", ""],
  "viktor-fonarik": ["assets/archive/viktor-fonarik.webp", "h43 old", "Два часа ночи, «Остров сокровищ» под одеялом. Сфотографировала и ничего не сказала. Утром положила ему на стол новую батарейку.", ""],
  "viktor-lager":   ["assets/archive/viktor-lager.webp", "h43 old", "Лагерь «Заря», июль 76-го. Прислали с родительским письмом. Вожатая пишет: девочки ходят за ним хвостом, а он смотрит на флаг.", ""],
  "viktor-vypusknoy": ["assets/archive/viktor-vypusknoy.webp", "h43 old", "Выпускной, 78-й. Весь класс гулял до утра на набережной, а Витя стоял в стороне и смотрел, как разводят мосты. Костюм купили на вырост, рукава подшивала сама.", ""],
  "viktor-provody": ["assets/archive/viktor-provody.webp", "v34 old", "Ноябрь 79-го, военкомат. Положила ему в сумку Чехова. Мариша ревела в рукав до самого автобуса. Я не плакала. Потом.", ""],
  "hospital":       ["assets/archive/hospital.webp", "h43 old", "Ташкент, госпиталь, весна 80-го. Пишет, что «немного поцарапало», а сам в бинтах: плечо и нога. Лёша привёз ему дыню с базара. Хороший мальчик.", ""],
  "viktor-wedding": ["assets/archive/viktor-wedding-torn.webp", "v34 old torn", "Май 85-го, Дворец на Английской. Свидетелем был Лёха. Остальное неважно.", "", "assets/archive/viktor-wedding.webp"],
  "viktor-naida-first": ["assets/archive/viktor-naida-first.webp", "h43", "От автора: Весна 1994-го, кинологический питомник. Найду, старую служебную овчарку, списали по возрасту. Кинолог предупредил, что к чужим она не идёт. Витя присел, достал сушку и подождал. Через пять минут она подошла и больше не уходила.", "'94 4 17"],
  "viktor-volvo":   ["assets/archive/viktor-volvo.webp", "h43", "От автора: Декабрь 1995-го, засада в «Вольво», шестой час. Витя ждёт клиента, который так и не придёт, и доедает предпоследнего «Мишку». Последнего оставит Лёше.", "'95 12 14"],
  "viktor-syrniki-96": ["assets/archive/viktor-syrniki-96.webp", "h43", "От автора: Воскресенье, апрель 1996-го. Витя жарит сырники по маминой тетрадке для Петьки и Анютки. Анютка съела четыре, Найда два.", "'96 4 14"],
  "viktor-night":   ["assets/archive/viktor-night.webp", "h43", "От автора: Три часа ночи, Витя не спит. «Мастер и Маргарита», мамин экземпляр с её карандашными пометками на полях. Пометки он перечитывает чаще, чем сам роман.", "'96 10 4"],
  "viktor-utro": ["assets/archive/viktor-utro.webp", "h43", "От автора: Воскресенье, сентябрь 96-го, редкое утро без вызовов. Сигарета, мамин Паустовский и «Маяк» на радиоле. Через десять минут позвонит Лёша, и утро кончится.", "'96 9 15"],
  "viktor-liteyny-forma": ["assets/archive/viktor-liteyny-forma.webp", "h43", "От автора: Литейный, 4, после совещания у начальства. Форму Витя надевает раза три в год и каждый раз выглядит в ней так, будто родился в фуражке. Сам он об этом не догадывается.", "'96 10 2"],
  "viktor-office": ["assets/archive/viktor-office.webp", "h43", "От автора: Кабинет на Литейном, одиннадцатый час вечера. Чай остыл, пепельница полная, дело не сходится. Витя улыбается: значит, почти сошлось.", "'96 10 9"],
  "viktor-dopros": ["assets/archive/viktor-dopros.webp", "h43", "От автора: Допросная, октябрь 96-го. Голос Витя не повышает никогда. Ему хватает подвинуть папку поближе и немного подождать.", "'96 10 11"],
  "viktor-home-forma": ["assets/archive/viktor-home-forma.webp", "h43", "От автора: Вечер после службы. Фуражка на крючке, галстук долой, а Найда встречает в прихожей так, будто его не было год.", "'96 10 2"],
  "viktor-divan": ["assets/archive/viktor-divan.webp", "h43", "От автора: Половина двенадцатого, по телевизору одна рябь. Китель брошен на диван, Найда спит у ног. Дойти до кровати сил уже нет.", "'96 10 3"],
  "viktor-cvety": ["assets/archive/viktor-cvety.webp", "h43", "От автора: Хризантемы с Автовского рынка, завёрнутые в «Смену». Полчаса стоял на площадке, прежде чем позвонить. Для майора, который ходит на вооружённых, это очень долго.", "'96 10 14"],
  "viktor-vecher": ["assets/archive/viktor-vecher.webp", "h43", "От автора: Поздний вечер, кухня. Снял рубашку, а в дверь позвонили.", "'96 10 6"],
  "viktor-banya": ["assets/archive/viktor-banya.webp", "h43", "От автора: Дача под Приозерском, рассвет. Сначала парилка, потом озеро, потом чай с тремя ложками сахара. Вопросы потом.", "'96 9 1"],
  "viktor-boks": ["assets/archive/viktor-boks.webp", "h43", "От автора: Зал на Стачек, вторник. Бокс с двенадцати лет, бинты до сих пор затягивает зубами, как учил тренер. Бьёт по-прежнему первым.", "'96 9 24"],
  "viktor-dozhd": ["assets/archive/viktor-dozhd.webp", "h43", "От автора: Набережная, октябрь 96-го, ливень. Зонта у Вити нет и никогда не было: зачем, если есть кожанка. Промок до нитки и смеётся.", "'96 10 12"],
  "viktor-apelsiny": ["assets/archive/viktor-apelsiny.webp", "h43", "От автора: Автовский рынок, суббота. Авоська апельсинов «да это так, по дороге». Один всегда подбрасывает на ходу. Пока ни одного не уронил.", "'96 10 5"],
  "viktor-gvozdiki": ["assets/archive/viktor-gvozdiki.webp", "h43", "От автора: Мокрый, гвоздики завёрнуты в газету, стоит в дверях и чешет затылок. Говорит, просто шёл мимо. В дождь. На пятый этаж.", "'96 10 16"],
  "viktor-syrniki-utro": ["assets/archive/viktor-syrniki-utro.webp", "h43", "От автора: Утро выходного. Мамина тетрадка открыта на сырниках, хотя рецепт он давно знает наизусть. Первый сырник всегда достаётся тому, кто проснулся.", "'96 9 22"],
  "viktor-pelmeni": ["assets/archive/viktor-pelmeni.webp", "h43", "От автора: Вечер, дождь, кухня. Мамин фартук в цветочек, мука на щеке. Лепит сотню на неделю вперёд, а в пятницу приходит Лёша, и сотни как не бывало.", "'96 10 8"],
  "viktor-gitara": ["assets/archive/viktor-gitara.webp", "h43", "От автора: Подоконник на кухне, чай в подстаканнике, сигарета за ухом. Под настроение достаёт гитару и тихо перебирает Высоцкого. Попросишь спеть, скажет, что не умеет. Умеет.", "'96 10 1"],
  "viktor-mishka": ["assets/archive/viktor-mishka.webp", "h43", "От автора: Ларёк звукозаписи у «Автово», третий заход за неделю. «Наутилуса» всё нет. Зато есть «Мишка», кроссворд и повод зайти завтра.", "'96 10 10"],
  "duo-banya": ["assets/archive/duo-banya.webp", "h43", "От автора: Баня у Жоры, четверг. Витя с веником, Лёша с кружкой кваса. Жетоны оба так и не сняли с восьмидесятого.", "'96 10 3"],
  "duo-perekur": ["assets/archive/duo-perekur.webp", "h43", "От автора: Лестница на Литейном, перекур. Спичка одна на двоих, как в Афгане. Говорят про работу и смеются тоже над работой.", "'96 10 8"],
  "duo-planerka": ["assets/archive/duo-planerka.webp", "h43", "От автора: После планёрки. Лёша объясняет, что так дела не делаются. Витя курит, закинув ноги на стол, и соглашается со всем, кроме главного.", "'96 10 10"],
  "nardy":         ["assets/archive/nardy.webp", "h43", "От автора: Кухня у Вити, ночь. Нарды, «Пшеничная», пельмени на газете. Лёша проигрывает третью партию подряд и делает вид, что думает. Найда ждёт пельмень.", "'96 3 8"],

  "lesha-pirozhki": ["assets/archive/lesha-pirozhki.webp", "v34 old", "Лёшенька лепит пирожки, 68-й. Слепил четыре, съел шесть. Мука была везде, даже в коридоре.", ""],
  "lesha-football": ["assets/archive/lesha-football.webp", "v23 old", "Наш двор, 71-й. Мяч Генкин, но Лёша считает, что общий. Через пять минут разбили окно на втором этаже. Не он. Говорит.", ""],
  "lesha-papa":     ["assets/archive/lesha-papa.webp", "h32 old", "С папой в мастерской на Кировском, 74-й. Папа сказал: «Руки растут откуда надо». Лёша год этим хвастался всему двору.", ""],
  "lesha-tram":     ["assets/archive/lesha-tram.webp", "v34 old", "От автора: 1977-й, трамвайное кольцо у «Автово». Два билета на «Служебный роман». Девушка не пришла. Лёша посмотрел фильм два раза: один за себя, другой за неё.", ""],
  "lesha-vals":     ["assets/archive/lesha-vals.webp", "v34 old", "Выпускной, 78-й. Вальс со Светкой Ковалёвой, весь класс смотрел, физручка плакала. С тех пор Лёша всем говорит, что танцевать не умеет.", ""],
  "lesha-provody":  ["assets/archive/lesha-provody.webp", "v34 old", "Московский вокзал, ноябрь 79-го. Мама поправляет воротник в десятый раз. В сумке двадцать пирожков, до Термеза не доехал ни один.", ""],
  "lesha-vokzal":   ["assets/archive/lesha-vokzal.webp", "v34 old", "Ноябрь 81-го, тот же вокзал. Вернулись. Лёха сел, закурил и десять минут никуда не шёл. Снимал Витя.", ""],
  "lesha-mama":     ["assets/archive/lesha-mama.webp", "v34", "Мама и Лёша, май 95-го. Пирожки с капустой, «ешь, худой совсем». Съел двенадцать.", "'95 5 14"],
  "lesha-pirat":    ["assets/archive/lesha-pirat.webp", "h43", "Лёша дома. Пират опять уснул на кителе, будить нельзя. В отдел поедет в свитере.", "'96 2 11"],
  "pirat-plaid":    ["assets/archive/pirat-plaid.webp", "sq", "Пират спит на Лёшиной фуражке. Фуражку не отдаёт, Лёша неделю ходит без неё.", ""],
  "lesha-sofa":     ["assets/archive/lesha-sofa.webp", "v23", "От автора: Выходной. Лёша спит на диване, Пират спит на Лёше. Тельняшку он носит с 80-го и уверяет, что это уже другая.", "'96 3 3"],
  "pirat-window":   ["assets/archive/pirat-window.webp", "v34", "Пират на окне, следит за бабками во дворе. Подмигивает, или это глаза нет. Огурцы не трогать, Лёшины.", ""],
  "lesha-mama-album": ["assets/archive/lesha-mama-album.webp", "v23", "Мама показывает Вите Лёшины детские фотографии. Все. По второму кругу. Лёша просит его застрелить. Снимал Витя.", "'96 8 25"],
  "lesha-borsch":   ["assets/archive/lesha-borsch.webp", "v34", "Борщ по маминому рецепту. Пробует пятый раз и говорит, что чего-то не хватает. По рецепту пробовать надо три.", "'96 9 15"],
  "lesha-flowers":  ["assets/archive/lesha-flowers.webp", "v34", "У мамы день рождения. Хризантемы с Автовского рынка. Денег не взяли: «Алексей Петрович, да что вы». Оставил всё равно.", "'96 9 29"],
  "lesha-garage":   ["assets/archive/lesha-garage.webp", "v23", "Гараж, октябрь. Папин «Москвич». Не ездит с прошлого года, но Лёша каждое воскресенье что-нибудь в нём чинит.", "'96 10 6"],
  "lesha-niva":     ["assets/archive/lesha-niva.webp", "h32", "Октябрь 96-го. Лёха на капоте «Нивы» под дождём, второй час ночи. Спрашиваю: чего не в машине? «Подумать надо». О чём, не сказал.", "'96 10 9"]
};

